{"nodes":[{"id":"start_0","type":"start","meta":{"position":{"x":180,"y":89.5}},"data":{"title":"Start","outputs":{"type":"object","properties":{"key":{"type":"string","default":"","description":"高德Key"},"keywords":{"type":"string","default":"来优品","description":"地点关键字"},"filePath":{"type":"string","extra":{"index":3},"description":"写文件路径"},"region":{"type":"string","extra":{"index":4},"description":"行政区划编码，多个使用逗号分隔"}},"required":["key","keywords","filePath","region"]}}},{"id":"end_0","type":"end","meta":{"position":{"x":1100,"y":89.5}},"data":{"title":"End","inputsValues":{},"inputs":{"type":"object","properties":{}}}},{"id":"code_GCIN1","type":"code","meta":{"position":{"x":640,"y":0}},"data":{"title":"Code_1","inputsValues":{"key":{"type":"ref","content":["start_0","key"],"extra":{"index":0}},"keywords":{"type":"ref","content":["start_0","keywords"],"extra":{"index":1}},"filePath":{"type":"ref","content":["start_0","filePath"],"extra":{"index":2}},"region":{"type":"ref","content":["start_0","region"],"extra":{"index":3}}},"script":{"language":"xlang","content":"<c:script>
 import cn.hutool.http.HttpUtil;
 import cn.hutool.core.thread.ThreadUtil;
 import cn.hutool.core.io.FileUtil;
 import cn.hutool.core.util.ReflectUtil;
 import cn.hutool.core.map.MapUtil;

 // 初始化参数
 let pageSize = 10;
 let maxPages = 100000;
 let allResults = [];

 // 分割region参数
 logInfo("region:{}", region);
 let regions = region.split(",");

 for(let r = 0; r < regions.length; r++) {
 let currentRegion = regions[r].trim();
 let page = 1;

 while(page <= maxPages) {
 // 构建请求URL
 let url = "https://restapi.amap.com/v5/place/text?key=" + key +
 "&keywords=" + keywords +
 "&page_size=" + pageSize +
 "&page_num=" + page +
 "&city_limit=true&region=" + currentRegion;

 // 使用HTTP工具发送GET请求
 let res = HttpUtil.get(url);

 // 解析响应
 let response = $JSON.parse(res);

 // 检查是否有错误
 if(response.status != "1") {
 logError("API请求失败: {}", response.info);
 break;
 }

 // 获取当前页的数据
 let pois = response.pois || [];

 // 如果没有更多数据则退出循环
 if(pois.length == 0) {
 logInfo("【{}】已获取所有数据,共 {} 页", currentRegion, page - 1);
 break;
 }

 // 添加到总结果中
 allResults = allResults.concat(pois);

 // 打印当前页数据
 logInfo("【{}】第 {} 页数据({} 条):", currentRegion, page, pois.length);

 // 增加页码继续下一页
 page++;
 ThreadUtil.sleep(500);
 }
 }

 // 最终统计信息
 logInfo("===== 数据获取完成 =====");
 logInfo("总获取记录数:{} 条", allResults.length);
 logInfo("涉及区域数量:{} 个", regions.length);

 // 生成CSV并写入文件
 if(allResults.length > 0) {
 // 获取第一个对象的所有键作为表头
 let firstObj = allResults[0];
 let headers = [];

 // 如果是 Map 类型
 if(firstObj instanceof java.util.Map) {
 headers = new java.util.ArrayList(firstObj.keySet());
 } else {
 // 如果是普通对象,使用反射获取字段
 let fields = ReflectUtil.getFields(firstObj.getClass());
 for(let i = 0; i < fields.length; i++) {
 headers.push(fields[i].getName());
 }
 }

 let csvContent = headers.join(",") + "\n";
 logInfo("headers:{}", csvContent);

 // 遍历数据生成CSV内容
 for(let i = 0; i < allResults.length; i++) {
 let row = [];
 for(let h = 0; h < headers.length; h++) {
 let headerName = headers[h];
 let value = "";

 if(allResults[i] instanceof java.util.Map) {
 value = allResults[i].get(headerName);
 } else {
 value = ReflectUtil.getFieldValue(allResults[i], headerName);
 }

 if(value != null) {
 value = $String.replace(value, ",", "_");
 } else {
 value = "";
 }
 row.push(value);
 }
 csvContent += row.join(",") + "\n";
 }

 // 写入本地文件
 FileUtil.writeUtf8String(csvContent, filePath);
 logInfo("CSV文件写入成功,路径:{}", filePath);
 } else {
 logInfo("没有数据可写入CSV文件");
 }

 // 返回输出
 return {
 dataSize: allResults.length,
 regionsCount: regions.length,
 csvFilePath: allResults.length > 0 ? filePath : null
 };

</c:script>
"},"outputs":{"type":"object","properties":{"dataSize":{"type":"integer","extra":{"index":1}}},"required":["dataSize"]},"inputs":{"type":"object","properties":{"key":{"type":"string"},"keywords":{"type":"string"},"filePath":{"type":"string"},"region":{"type":"string"}}}}}],"edges":[{"sourceNodeID":"start_0","targetNodeID":"code_GCIN1"},{"sourceNodeID":"code_GCIN1","targetNodeID":"end_0"}]}
